    ('06c1a0d2-6ae6-5353-a2af-1d5ba21f346e'::uuid, '94602fa0-6f2c-55e4-9bc0-b111e39e1da7'::uuid, 'Qui fonde la dynastie carolingienne en 751 ?', 'mcq', '["Pépin le Bref","Clovis","Charlemagne","Louis le Pieux"]'::jsonb, 0, 'Il écarte les Mérovingiens avec l’appui du pape.', 1),
