    ('41d556ba-42b2-5f96-803e-fc5a5ace3ca5'::uuid, '94602fa0-6f2c-55e4-9bc0-b111e39e1da7'::uuid, 'Qu’est-ce que la minuscule caroline ?', 'mcq', '["Une écriture nouvelle, plus lisible, ancêtre de nos minuscules","Une école palatine","Un impôt sur les monastères","Une langue parlée à la cour"]'::jsonb, 0, 'Elle naît dans les scriptoria de la renaissance carolingienne.', 6),
    ('387ba1d9-af57-5e00-846e-195d6a6bb576'::uuid, '94602fa0-6f2c-55e4-9bc0-b111e39e1da7'::uuid, 'Que fait le traité de Verdun en 843 ?', 'mcq', '["Il partage l’empire entre les trois petits-fils de Charlemagne","Il couronne Charlemagne empereur","Il met fin aux invasions vikings","Il réunifie l’Occident"]'::jsonb, 0, 'Francie occidentale, Lotharingie, Francie orientale.', 7),
    ('ce5d5b6c-bedb-58c3-aa8a-f612f9565433'::uuid, '94602fa0-6f2c-55e4-9bc0-b111e39e1da7'::uuid, 'Charlemagne savait parfaitement lire et écrire dès son enfance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il a appris à lire tardivement, et n’a jamais bien maîtrisé l’écriture — ce qui ne l’a pas empêché de promouvoir les écoles.', 8),
    ('6af324f6-3b83-55ab-a504-582c72d21700'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Quelles trois civilisations se côtoient en Méditerranée au Moyen Âge ?', 'mcq', '["La chrétienté latine, la chrétienté orthodoxe et le monde musulman","Rome, Byzance et la Chine","Les Francs, les Vikings et les Arabes","L’Espagne, l’Italie et l’Égypte"]'::jsonb, 0, 'Elles s’affrontent et échangent en même temps.', 1),
    ('f8bf1fb3-8dd5-57bb-ae9f-b3aef1f8b8a0'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Qui appelle à la première croisade en 1095 ?', 'mcq', '["Le pape Urbain II","Charlemagne","Saladin","L’empereur byzantin Justinien"]'::jsonb, 0, 'Il s’agit de reprendre Jérusalem.', 2),
    ('7e2999b8-d3bd-5b70-b3dc-49f16a628b65'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Qui reprend Jérusalem aux croisés en 1187 ?', 'mcq', '["Saladin","Mehmed II","Le calife de Bagdad","Richard Cœur de Lion"]'::jsonb, 0, 'Jérusalem avait été prise par les croisés en 1099.', 3),
    ('281ca0cc-0d91-5e31-a231-e485d6893f75'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Que fait la quatrième croisade en 1204 ?', 'mcq', '["Elle pille Constantinople, ville chrétienne","Elle reprend Jérusalem","Elle conquiert l’Égypte","Elle échoue avant d’embarquer"]'::jsonb, 0, 'Des chrétiens contre des chrétiens.', 4),
    ('6ea8957a-7439-5b35-81bc-98c6f368cf7f'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Quelles villes italiennes dominent le commerce méditerranéen ?', 'mcq', '["Venise, Gênes et Pise","Rome, Naples et Milan","Florence, Sienne et Vérone","Palerme, Bari et Amalfi seulement"]'::jsonb, 0, 'Elles installent des comptoirs dans tout le bassin.', 5),
    ('c669e7e5-027d-58d7-9b05-e569f1c03d26'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Quelle ville espagnole est un grand centre de traduction ?', 'mcq', '["Tolède","Grenade","Séville","Barcelone"]'::jsonb, 0, 'Chrétiens, juifs et musulmans y traduisent les textes grecs conservés en arabe.', 6),
    ('a7f1aa26-51a1-5f6e-b2e6-f77079e6897a'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Quel savoir mathématique l’Occident reçoit-il par le monde musulman ?', 'mcq', '["La numération indo-arabe, le zéro et l’algèbre","La géométrie euclidienne uniquement","Le calcul des probabilités","La trigonométrie sphérique seule"]'::jsonb, 0, 'Le vocabulaire en garde la trace : algèbre, chiffre, zéro.', 7),
    ('31d1eab3-15f8-55c3-a078-035bf9c01a68'::uuid, 'aa03ca61-3b81-53ce-ba20-aa197bb49bc0'::uuid, 'Les guerres ont interrompu le commerce en Méditerranée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’a jamais cessé : les mêmes routes portaient les armées et les marchandises.', 8),
    ('20c05619-dba5-54d0-b48d-2873cba10bfa'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'Quels sont les trois ordres de la société médiévale ?', 'mcq', '["Ceux qui prient, ceux qui combattent, ceux qui travaillent","Les nobles, les bourgeois, les esclaves","Le roi, les seigneurs, les serfs","Les clercs, les marchands, les artisans"]'::jsonb, 0, 'Les paysans représentent environ 90 % de la population.', 1),
    ('6e7e82fc-63d2-5f06-9887-8147750287f3'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'Comment appelle-t-on la partie de la seigneurie exploitée directement par le seigneur ?', 'mcq', '["La réserve","La tenure","Le fief","Le ban"]'::jsonb, 0, 'Les tenures sont concédées aux paysans.', 2),
    ('0b5e69fa-da00-5e8a-87bd-eaa8dee39917'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'Quelle est la différence entre un vilain et un serf ?', 'mcq', '["Le vilain est libre, le serf est attaché à la terre","Le vilain est plus riche","Le serf ne paie aucune redevance","Le vilain appartient au clergé"]'::jsonb, 0, 'Le serf doit des obligations supplémentaires.', 3),
    ('2d74c0f1-33d6-5890-81cb-ab06712973bf'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'Que sont les banalités ?', 'mcq', '["Des taxes pour l’usage obligatoire du moulin, du four et du pressoir","Des corvées agricoles","Des impôts royaux","Des amendes judiciaires"]'::jsonb, 0, 'Elles s’ajoutent au cens et au champart.', 4),
    ('abaad0f2-1493-500c-af78-5b57e43b0542'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'Qu’est-ce que la dîme ?', 'mcq', '["Une redevance d’environ un dixième de la récolte versée à l’Église","Une taxe seigneuriale sur le moulin","Un impôt royal sur le sel","Un droit de passage sur les ponts"]'::jsonb, 0, 'Elle finance le clergé et l’entretien des églises.', 5),
    ('447b91d5-6069-50ee-9cd3-d23dbb7822ae'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'Quel progrès technique améliore le travail du cheval ?', 'mcq', '["Le collier d’épaule","La charrue romaine","Le joug frontal","La faux à deux mains"]'::jsonb, 0, 'Il permet au cheval de tirer sans s’étrangler.', 6),
    ('4362ac78-71e1-5056-9e96-7fbe3e6d6d0a'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'Que reçoit un vassal en échange de son hommage ?', 'mcq', '["Un fief, le plus souvent une terre","Une somme d’argent annuelle","Un titre de noblesse héréditaire","Une charge religieuse"]'::jsonb, 0, 'Il doit en retour aide et conseil à son suzerain.', 7),
    ('08a9e27d-02a7-56ff-a09a-b5981d45fba2'::uuid, '5ab92222-88e8-5e67-9041-0cd4f52ae5b5'::uuid, 'La peste noire du XIVe siècle a eu peu d’effets sur la société féodale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle emporte environ un tiers de la population européenne et ébranle tout le système.', 8),
    ('20093d8e-1687-5cdf-a9be-7c5d0c95553b'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Combien y a-t-il de sacrements dans l’Église médiévale ?', 'mcq', '["Sept","Cinq","Trois","Dix"]'::jsonb, 0, 'Du baptême à l’extrême-onction, ils jalonnent toute la vie.', 1),
    ('0a0e5756-57bb-56f9-82dd-21ba7794784e'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Quelle est la différence entre clergé séculier et clergé régulier ?', 'mcq', '["Le séculier vit au contact des fidèles, le régulier suit une règle à l’écart","Le séculier est plus riche","Le régulier ne prononce pas de vœux","Le séculier dépend du roi"]'::jsonb, 0, 'Curés et évêques d’un côté, moines de l’autre.', 2),
    ('ddd548c8-afaa-5b31-a558-0ab2dc209ca4'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Quels ordres apparaissent au XIIIe siècle et prêchent dans les villes ?', 'mcq', '["Les ordres mendiants, franciscains et dominicains","Les bénédictins","Les cisterciens","Les templiers"]'::jsonb, 0, 'Ils vivent d’aumônes.', 3),
    ('26f8f4f1-bef1-51a5-9346-a433a66745c1'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Quelle est la principale ressource financière de l’Église ?', 'mcq', '["La dîme et ses domaines fonciers","Les impôts royaux","Le commerce maritime","Les droits de péage"]'::jsonb, 0, 'Elle est le premier propriétaire foncier d’Occident.', 4),
    ('bcf8f870-b06a-5108-b870-dcbf1cc6e4bd'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Qu’est-ce qui caractérise l’art gothique ?', 'mcq', '["La croisée d’ogives, les arcs-boutants et les grands vitraux","Les voûtes en plein cintre et les murs épais","L’absence de sculptures","Les coupoles et les mosaïques"]'::jsonb, 0, 'L’art roman, lui, est massif et sombre.', 5),
    ('c63865f5-77df-5df4-a2ca-9e7a7863e1ed'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Pourquoi les vitraux et les sculptures racontent-ils la Bible ?', 'mcq', '["Parce que la population ne sait pas lire","Parce que les textes étaient interdits","Pour décorer les églises uniquement","Pour remplacer les sermons"]'::jsonb, 0, 'L’image est le livre de ceux qui ne lisent pas.', 6),
    ('31522172-c49e-501a-9cf2-d170300f84d5'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Qu’est-ce que l’excommunication ?', 'mcq', '["L’exclusion d’un fidèle de la communauté chrétienne","Une amende versée à l’évêque","Un pèlerinage obligatoire","Une taxe sur les monastères"]'::jsonb, 0, 'Prononcée contre un roi, c’est une arme redoutable.', 7),
    ('1d6a1f98-490c-5ea3-acb4-310f967c2bfd'::uuid, '52bc35d0-7e98-51eb-b8bd-98b07638afd0'::uuid, 'Au Moyen Âge, être chrétien relevait d’un choix personnel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Presque tous étaient baptisés : c’était une condition, pas un choix.', 8),
    ('fde46e00-9728-54ce-9d5d-a3f9fa6bff6d'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'Quelles causes expliquent la renaissance urbaine des XIe-XIIIe siècles ?', 'mcq', '["Les progrès agricoles, la croissance de la population et la reprise du commerce","La fin des croisades","L’effondrement des campagnes","La création des universités"]'::jsonb, 0, 'Les trois se combinent.', 1),
    ('dff3bde8-765b-5c99-995c-f8d8f169aacf'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'Quelles foires réunissent marchands du Nord et du Sud ?', 'mcq', '["Les foires de Champagne","Les foires de Flandre","Les foires de Lombardie","Les foires de Bourgogne"]'::jsonb, 0, 'À Troyes et à Provins notamment.', 2),
    ('ac45ec83-69f0-51ae-97c5-7727ccc2bc0e'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'De quoi vivent les villes flamandes comme Bruges et Gand ?', 'mcq', '["Du drap","De la banque","Des épices","Du sel"]'::jsonb, 0, 'Les villes italiennes, elles, vivent du commerce méditerranéen et de la banque.', 3),
    ('9537f912-14fe-5376-9394-9f45b7e6ce7a'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'Qu’est-ce qu’une corporation ?', 'mcq', '["Une organisation de métier qui fixe règles, qualité et apprentissage","Un conseil municipal élu","Une association de marchands étrangers","Une confrérie religieuse"]'::jsonb, 0, 'Apprenti, compagnon, maître : la hiérarchie y est stricte.', 4),
    ('a26ecaaf-fc98-5bec-a38b-d4360052e3a8'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'Qu’est-ce qu’une charte de franchises ?', 'mcq', '["Un document accordant à une ville le droit de s’administrer","Un contrat de vente entre marchands","Un privilège accordé aux seigneurs","Un impôt urbain"]'::jsonb, 0, 'Les villes élisent alors échevins ou consuls.', 5),
    ('a9a7d60e-7c31-5285-ac30-a466c485683b'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'Que signifie « l’air de la ville rend libre » ?', 'mcq', '["Un serf y vivant un an et un jour sans être réclamé devenait libre","La ville était plus saine que la campagne","Les villes ne payaient pas d’impôts","Les bourgeois pouvaient voyager sans autorisation"]'::jsonb, 0, 'La ville est un statut autant qu’un lieu.', 6),
    ('df565f0f-18e8-54a9-8343-f3245d8ba82b'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'Quelle organisation domine le commerce de la mer du Nord et de la Baltique ?', 'mcq', '["La Hanse germanique","La ligue lombarde","La Sérénissime","La ligue de Champagne"]'::jsonb, 0, 'Un réseau de villes marchandes.', 7),
    ('7232043c-967d-5b7b-b609-b33396b58f14'::uuid, '5f625312-9c65-5afb-9f77-5046d92af47b'::uuid, 'Les villes médiévales étaient des lieux salubres et sûrs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Denses et sales, elles étaient exposées aux incendies et aux épidémies.', 8),
    ('e021c387-8c11-5d50-a747-7a91ae28e46f'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'En quelle année Hugues Capet est-il élu roi ?', 'mcq', '["987","1214","1337","1429"]'::jsonb, 0, 'Son domaine se limitait alors aux environs de Paris et d’Orléans.', 1),
    ('60be4a0d-8f76-5194-969e-cbeaef357470'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'Où les rois de France sont-ils sacrés ?', 'mcq', '["À Reims","À Paris","À Saint-Denis","À Orléans"]'::jsonb, 0, 'Le sacre les rend « rois par la grâce de Dieu ».', 2),
    ('3f55aff4-d796-5d94-a838-e11812e4ad0f'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'Comment s’appellent les agents royaux du nord du royaume ?', 'mcq', '["Les baillis","Les sénéchaux","Les échevins","Les légistes"]'::jsonb, 0, 'Les sénéchaux exercent la même fonction au sud.', 3),
    ('a8ccf0d0-5564-5aaf-b206-92f9b1e3e4f3'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'Quel roi l’emporte à Bouvines en 1214 ?', 'mcq', '["Philippe Auguste","Saint Louis","Philippe le Bel","Charles VII"]'::jsonb, 0, 'Il triple le domaine royal pendant son règne.', 4),
    ('3fd5e883-1ac7-569d-9c37-30ed412e236f'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'Quel roi réunit les premiers États généraux en 1302 ?', 'mcq', '["Philippe le Bel","Hugues Capet","Saint Louis","Charles VII"]'::jsonb, 0, 'Il s’oppose alors au pape Boniface VIII.', 5),
    ('59da4ca4-23f1-5e15-8c7c-f17877dbb29c'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'Quelles sont les dates de la guerre de Cent Ans ?', 'mcq', '["1337-1453","1214-1314","1095-1291","1429-1492"]'::jsonb, 0, 'Elle oppose Valois et Plantagenêts pour la couronne de France.', 6),
    ('649864cc-6e0a-5903-b4a3-faa0cd1ca8cd'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'Quel rôle joue Jeanne d’Arc ?', 'mcq', '["Elle fait sacrer Charles VII à Reims en 1429","Elle gagne la bataille d’Azincourt","Elle négocie le traité de Troyes","Elle règne après Charles VI"]'::jsonb, 0, 'Son intervention renverse le cours de la guerre.', 7),
    ('70cf7a5d-2aca-5b89-a47b-235d8d6553ab'::uuid, '96a9db0a-c342-5a4f-9011-731c1c1eb99a'::uuid, 'Le royaume de France sort affaibli et désorganisé de la guerre de Cent Ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en sort avec une armée et un impôt permanents : l’État moderne est en place.', 8),
    ('9eade4b1-7478-580b-8f7f-59d373b085cb'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Quel événement de 1453 gêne les routes terrestres vers l’Asie ?', 'mcq', '["La prise de Constantinople par les Ottomans","La chute de Grenade","Le traité de Tordesillas","La mort de Charles VII"]'::jsonb, 0, 'L’Europe cherche alors une route maritime.', 1),
    ('b8d09fe9-2186-5c4f-bce0-d9769209d5f5'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Quelle invention n’a PAS aidé les grandes découvertes ?', 'mcq', '["La machine à vapeur","La caravelle","La boussole","L’astrolabe"]'::jsonb, 0, 'La machine à vapeur date du XVIIIe siècle.', 2),
    ('694848c1-220b-516f-8569-c77381cc121e'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Qui atteint l’Amérique en 1492 ?', 'mcq', '["Christophe Colomb","Vasco de Gama","Magellan","Bartolomeu Dias"]'::jsonb, 0, 'Il cherchait les Indes et mourra convaincu d’avoir touché l’Asie.', 3),
    ('d5c56217-f990-5bd5-8e68-ced8ebb54e87'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Qui atteint l’Inde par la mer en 1498 ?', 'mcq', '["Vasco de Gama","Christophe Colomb","Cortés","Pizarro"]'::jsonb, 0, 'Il contourne l’Afrique par le cap de Bonne-Espérance.', 4),
    ('fa4a539a-f2ea-5ccf-a798-a79c43734045'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Que fait le traité de Tordesillas en 1494 ?', 'mcq', '["Il partage le monde à découvrir entre le Portugal et l’Espagne","Il interdit la traite des esclaves","Il met fin à la guerre de Cent Ans","Il fixe les frontières de l’Amérique"]'::jsonb, 0, 'Une ligne tracée sur une carte, loin des terres concernées.', 5),
    ('8ba9ec30-40c4-5e40-81e2-dcf719f4e08b'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Quel empire Cortés détruit-il en 1521 ?', 'mcq', '["L’empire aztèque","L’empire inca","L’empire maya","L’empire ottoman"]'::jsonb, 0, 'Pizarro abat celui des Incas en 1533.', 6),
    ('d96a0c95-f5a6-578f-a0e8-4555038a13b5'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Quelle est la principale cause de l’effondrement démographique amérindien ?', 'mcq', '["Les maladies européennes, contre lesquelles les populations n’étaient pas immunisées","Les seules armes à feu","La famine organisée","Le départ vers l’Europe"]'::jsonb, 0, 'Variole et rougeole emportent 80 à 90 % de la population en un siècle.', 7),
    ('c6f380a4-9f80-5c7b-99c9-bd31c26b7a4d'::uuid, 'ef8c5791-07f8-536c-b019-ba74358c10e8'::uuid, 'Les terres atteintes en 1492 étaient inhabitées.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles étaient peuplées et organisées depuis des millénaires : « découverte » est un mot européen.', 8),
    ('8f914ed0-fa9f-59f1-8e6d-84eb68e2d10d'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'Quels territoires Charles Quint réunit-il ?', 'mcq', '["L’Espagne, les Pays-Bas, l’Autriche, l’Empire et l’Amérique espagnole","La France et l’Angleterre","L’Italie et la Grèce","La Hongrie et les Balkans"]'::jsonb, 0, 'D’où la formule : « le soleil ne se couche jamais » sur son empire.', 1),
    ('da4aa912-b227-5e9f-95e7-47722ed4b81f'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'En quelle année Charles Quint est-il élu empereur ?', 'mcq', '["1519","1500","1556","1571"]'::jsonb, 0, 'Il abdiquera en 1556, épuisé.', 2),
    ('6e486886-ecfe-5742-b408-bf4d2bccbbe4'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'Quel roi de France combat Charles Quint ?', 'mcq', '["François Ier","Louis XI","Henri IV","Louis XIV"]'::jsonb, 0, 'Marignan, puis la défaite de Pavie.', 3),
    ('defc2dae-4a04-54a4-bd2f-4bcc7e713fed'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'Quel sultan ottoman porte l’empire à son apogée au XVIe siècle ?', 'mcq', '["Soliman le Magnifique","Mehmed II","Saladin","Bayezid"]'::jsonb, 0, 'Il règne de 1520 à 1566.', 4),
    ('d7498ffa-91e9-5108-9b91-79f7b847495b'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'Quelle ville Soliman assiège-t-il en 1529 sans la prendre ?', 'mcq', '["Vienne","Rome","Venise","Madrid"]'::jsonb, 0, 'C’est la limite de son expansion vers l’ouest.', 5),
    ('78a2ead6-295e-510d-9037-7eba5d4e4be0'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'Pourquoi appelle-t-on Soliman « Kanuni » en turc ?', 'mcq', '["Parce qu’il réorganise le droit de l’empire : c’est « le législateur »","Parce qu’il a conquis le plus de terres","Parce qu’il a bâti Istanbul","Parce qu’il était le plus jeune sultan"]'::jsonb, 0, 'Le surnom « le Magnifique » est européen.', 6),
    ('99bf83ab-f19f-5036-b665-5af399963d45'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'Quelle alliance surprenante François Ier conclut-il ?', 'mcq', '["Une alliance avec Soliman, sultan musulman","Une alliance avec Charles Quint","Une alliance avec le pape contre Venise","Une alliance avec l’Angleterre protestante"]'::jsonb, 0, 'Elle montre que la politique l’emporte sur la religion.', 7),
    ('11b821a4-326a-5db6-ab3d-c5ea7239ad4e'::uuid, '8fb5d03a-ac17-5978-ab7d-80395ba22ae3'::uuid, 'Charles Quint a transmis son empire entier à son fils Philippe II.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’a partagé : l’Espagne à Philippe II, l’Autriche à son frère Ferdinand.', 8),
    ('baaec5d1-0b7c-52b1-9a06-fff46872c7a3'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Qu’est-ce que l’humanisme ?', 'mcq', '["Un mouvement qui place l’être humain et sa raison au centre de la réflexion","Un rejet de toute religion","Une doctrine politique républicaine","Un courant artistique uniquement"]'::jsonb, 0, 'Il ne rompt pas avec la foi.', 1),
    ('096dab3f-4124-5836-98ab-a17c9e53c13b'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Que prônent les humanistes à propos des textes antiques ?', 'mcq', '["Y revenir dans leur langue d’origine et les critiquer","Les interdire","Les traduire uniquement en latin","Les remplacer par des textes modernes"]'::jsonb, 0, 'Grec, latin et hébreu redeviennent des langues d’étude.', 2),
    ('fb320a5e-3eb5-5fba-9b38-631b139a2594'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Quel humaniste est surnommé le « prince des humanistes » ?', 'mcq', '["Érasme","Thomas More","Rabelais","Montaigne"]'::jsonb, 0, 'Il édite le Nouveau Testament en grec.', 3),
    ('3be5fc1d-b427-5c2a-9fc5-82f0c49c0a2a'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Qui met au point l’imprimerie à caractères mobiles vers 1450 ?', 'mcq', '["Gutenberg","Érasme","Léonard de Vinci","Copernic"]'::jsonb, 0, 'À Mayence, en Allemagne.', 4),
    ('61a7c738-2d53-5a3e-af6b-4c6a73d1e966'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Quelle conséquence l’imprimerie a-t-elle sur l’Église ?', 'mcq', '["Elle lui fait perdre le contrôle de la diffusion des textes","Elle renforce son autorité","Elle lui donne un monopole sur les livres","Elle n’a aucun effet"]'::jsonb, 0, 'Cela pèsera lourd pendant la Réforme.', 5),
    ('6ce73b2e-457b-5a0a-b813-9afe73276f97'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Qui affirme en 1543 que la Terre tourne autour du Soleil ?', 'mcq', '["Copernic","Vésale","Ambroise Paré","Galilée"]'::jsonb, 0, 'C’est la thèse de l’héliocentrisme.', 6),
    ('43ebdfbb-039c-5e1f-96a0-f8cbfcd89b44'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Quelle famille florentine protège les artistes de la Renaissance ?', 'mcq', '["Les Médicis","Les Borgia","Les Habsbourg","Les Valois"]'::jsonb, 0, 'Ce sont des mécènes.', 7),
    ('04e62b84-2a3c-5395-9ec7-7a21f03c2357'::uuid, '96653120-1e5a-519e-91ad-8b0818b97199'::uuid, 'Les humanistes rejetaient la religion chrétienne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils la réinterrogent à partir des textes originaux, sans la rejeter.', 8),
    ('9fc5a4e4-6458-565e-b5b1-f5c52ab18f29'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'Que dénonce Luther en 1517 dans ses 95 thèses ?', 'mcq', '["Le commerce des indulgences","Le célibat des prêtres uniquement","L’existence du pape","La traduction de la Bible"]'::jsonb, 0, 'Il affirme que le salut vient de la foi seule.', 1),
    ('c6e494ac-92a7-51ea-b0b2-1da7c661e670'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'Selon Luther, quelle est la seule autorité en matière de foi ?', 'mcq', '["La Bible","Le pape","Le concile","La tradition de l’Église"]'::jsonb, 0, 'Il la traduit en allemand pour que tous puissent la lire.', 2),
    ('81afb124-321c-56f4-9939-d0d318b5ffa2'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'Dans quelle ville Calvin développe-t-il sa doctrine ?', 'mcq', '["Genève","Wittenberg","Rome","Paris"]'::jsonb, 0, 'Il y organise strictement la cité.', 3),
    ('980e3042-202e-5730-ac82-7cfcb786c46b'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'Qu’est-ce que la prédestination ?', 'mcq', '["L’idée que Dieu a choisi d’avance ceux qui seront sauvés","La croyance en la réincarnation","Le refus des sacrements","L’obligation de lire la Bible chaque jour"]'::jsonb, 0, 'C’est la doctrine centrale du calvinisme.', 4),
    ('5038744c-b793-5b54-b13e-edcbc468134b'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'Quel concile organise la réaction catholique ?', 'mcq', '["Le concile de Trente","Le concile de Nicée","Le concile de Latran","Le concile de Genève"]'::jsonb, 0, 'Il siège de 1545 à 1563.', 5),
    ('8e89bc7f-4730-58b8-9561-9b4d5e4fdde0'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'Que se passe-t-il lors de la Saint-Barthélemy en 1572 ?', 'mcq', '["Plusieurs milliers de protestants sont massacrés","L’édit de Nantes est signé","Henri IV est couronné","Luther est excommunié"]'::jsonb, 0, 'À Paris puis en province.', 6),
    ('ee15daa1-a7af-50d3-bfc4-6cd93ba64b18'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'Qu’accorde l’édit de Nantes en 1598 ?', 'mcq', '["La liberté de conscience et un culte encadré aux protestants","L’égalité complète des religions","L’interdiction du catholicisme","La liberté de la presse"]'::jsonb, 0, 'Louis XIV le révoquera en 1685.', 7),
    ('735e1f55-6114-5c59-bdbb-9892329be207'::uuid, 'c6a80959-29e8-5e27-a685-d21071f42dab'::uuid, 'L’édit de Nantes proclame la tolérance religieuse au sens moderne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il organise une coexistence pour arrêter la guerre, ce qui n’est pas la même chose.', 8),
    ('7b5cd745-a218-547e-949a-522178883bcf'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'Qu’est-ce que la monarchie absolue ?', 'mcq', '["Un régime où le roi détient tous les pouvoirs, sans comptes à rendre","Un régime où le roi partage le pouvoir avec un parlement","Un régime électif","Un régime sans religion d’État"]'::jsonb, 0, 'Il tient son pouvoir de Dieu : c’est le droit divin.', 1),
    ('bb9df4ad-9cf4-5117-ac79-3e9d53cd5452'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'Quel ministre de Louis XIII soumet les grands nobles et crée les intendants ?', 'mcq', '["Richelieu","Mazarin","Colbert","Sully"]'::jsonb, 0, 'Il abat aussi les places fortes protestantes.', 2),
    ('7893c01c-9f03-5282-b4af-5750b53104e1'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'Qu’est-ce que la Fronde ?', 'mcq', '["Une révolte contre le pouvoir royal pendant la minorité de Louis XIV","Une guerre contre l’Espagne","Une révolte protestante","Un impôt nouveau"]'::jsonb, 0, 'Louis XIV en gardera un souvenir durable.', 3),
    ('f988749d-b87a-5f12-a39e-c5515e6dd41e'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'En quelle année Louis XIV décide-t-il de gouverner seul ?', 'mcq', '["1661","1643","1682","1685"]'::jsonb, 0, 'À la mort de Mazarin, il se passe de Premier ministre.', 4),
    ('36f1522f-26fe-5c57-88ba-99691c2de0ee'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'À quoi sert l’étiquette de Versailles ?', 'mcq', '["À domestiquer la noblesse en l’occupant à la cour","À former les futurs ministres","À réduire les dépenses royales","À organiser l’armée"]'::jsonb, 0, 'La cour y est fixée en 1682.', 5),
    ('5b8bfd6d-2e60-53fd-9652-e39d1c75d3c8'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'Quelle politique économique Colbert met-il en œuvre ?', 'mcq', '["Le mercantilisme : manufactures, marine, colonies, protectionnisme","Le libre-échange","La suppression des impôts","La collectivisation des terres"]'::jsonb, 0, 'Enrichir l’État par le commerce et la production.', 6),
    ('282b16b8-22da-5a0f-9366-6be71d7efce1'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'Quelle est la conséquence de la révocation de l’édit de Nantes en 1685 ?', 'mcq', '["Des dizaines de milliers de protestants quittent le royaume","Les protestants obtiennent l’égalité","La guerre reprend avec l’Espagne","Le pape excommunie Louis XIV"]'::jsonb, 0, 'Un désastre économique autant qu’humain.', 7),
    ('cd8ec56c-d5a3-50d5-b0f5-e9aeaa3bd400'::uuid, '3783f6c1-bd6e-5260-985e-18148d7b2680'::uuid, 'Le pouvoir absolu signifiait que le roi pouvait tout faire sans aucune limite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il restait tenu par les lois fondamentales du royaume et par les coutumes.', 8),
    ('bfa4ffd1-0669-5d16-b7f1-a2b2d6acc0b5'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Comment définit-on le développement durable ?', 'mcq', '["Un développement qui répond aux besoins du présent sans compromettre ceux des générations futures","Un développement qui dure longtemps","Une croissance économique rapide","Un développement sans industrie"]'::jsonb, 0, 'La définition vient du rapport Brundtland de 1987.', 1),
    ('1bd69f26-8f30-5797-aa35-547e9ffef92f'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Quels sont les trois piliers du développement durable ?', 'mcq', '["Économique, social et environnemental","Politique, culturel et religieux","Local, national et mondial","Agricole, industriel et tertiaire"]'::jsonb, 0, 'Un projet durable doit satisfaire les trois à la fois.', 2),
    ('1baf2fe7-ef17-564d-81e3-42bd0bed7b60'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Quel sommet de 1992 popularise la notion ?', 'mcq', '["Le sommet de Rio","Le sommet de Stockholm","Le sommet de Kyoto","Le sommet de Paris"]'::jsonb, 0, 'Il lance aussi les Agendas 21.', 3),
    ('05149c26-5292-5924-a695-175b3474b8ae'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Combien d’objectifs de développement durable l’ONU a-t-elle adoptés en 2015 ?', 'mcq', '["17","10","25","8"]'::jsonb, 0, 'À atteindre à l’horizon 2030.', 4),
    ('2443463c-8a0c-55e5-a3a0-a51253eebbf0'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Que combine l’indice de développement humain (IDH) ?', 'mcq', '["La richesse, l’espérance de vie et le niveau d’éducation","Le PIB et la population","La superficie et les ressources","Le nombre d’écoles et d’hôpitaux"]'::jsonb, 0, 'Il varie entre 0 et 1.', 5),
    ('1ad62fe8-6a13-5465-b85e-1e51d2ae816c'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Que mesure l’empreinte écologique ?', 'mcq', '["La surface nécessaire pour produire ce qu’on consomme et absorber ses déchets","La quantité de CO₂ émise par personne","Le nombre d’espèces disparues","La superficie des forêts"]'::jsonb, 0, 'Elle se mesure en hectares par habitant.', 6),
    ('68af26da-fd2b-5867-b652-577104b6f813'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Que vise l’accord de Paris de 2015 ?', 'mcq', '["Limiter le réchauffement bien en dessous de 2 °C","Interdire le charbon dans le monde","Créer une taxe mondiale sur le pétrole","Reboiser l’Amazonie"]'::jsonb, 0, 'Il engage l’ensemble des États signataires.', 7),
    ('4c1fb647-e1a5-592a-b2fe-2c521fcbb388'::uuid, '34cbaa1e-c417-57f5-bf37-d3ceb7dc50e5'::uuid, 'Le PIB par habitant suffit à mesurer le développement d’un pays.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il mesure la richesse produite, mais ni la santé, ni l’éducation, ni les inégalités.', 8),
    ('746992da-c0cf-5dc6-a061-a7a217cecb64'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'Combien d’humains la Terre comptait-elle en 2022 ?', 'mcq', '["8 milliards","5 milliards","10 milliards","6 milliards"]'::jsonb, 0, 'Contre 1 milliard vers 1800.', 1),
    ('e25c5563-9bfb-593b-9986-42584c84e900'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'Qu’est-ce que l’accroissement naturel ?', 'mcq', '["La différence entre le taux de natalité et le taux de mortalité","Le nombre total de naissances","La somme des migrations","Le nombre d’enfants par femme"]'::jsonb, 0, 'Il ne tient pas compte des migrations.', 2),
    ('5cf2817d-6895-5465-8576-172ea910b916'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'Quel est le seuil de renouvellement des générations ?', 'mcq', '["2,1 enfants par femme","1 enfant par femme","3 enfants par femme","2,5 enfants par femme"]'::jsonb, 0, 'En dessous, la population diminue à terme.', 3),
    ('27e3e870-73e4-559a-ac28-de82fb37925c'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'Que se passe-t-il pendant la deuxième phase de la transition démographique ?', 'mcq', '["La mortalité chute alors que la natalité reste élevée","La natalité chute avant la mortalité","Les deux taux baissent ensemble","Les deux taux augmentent"]'::jsonb, 0, 'C’est le moment de l’explosion démographique.', 4),
    ('f56e657f-8760-56af-872a-ff361e0afc44'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'Quel continent concentre près de 60 % de l’humanité ?', 'mcq', '["L’Asie","L’Afrique","L’Europe","L’Amérique"]'::jsonb, 0, 'L’Inde et la Chine dépassent chacune 1,4 milliard d’habitants.', 5),
    ('97fea025-5b05-59d6-b0d3-04d911814984'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'Quelle région est encore en pleine phase 2 de la transition ?', 'mcq', '["L’Afrique subsaharienne","L’Europe de l’Ouest","Le Japon","L’Amérique du Nord"]'::jsonb, 0, 'Sa population croît encore rapidement.', 6),
    ('92be5f05-d7d2-5be9-b100-1d4beabdc446'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'Quel problème démographique connaissent les pays du Nord ?', 'mcq', '["Le vieillissement de la population","Une natalité trop forte","Une mortalité infantile élevée","Un manque de logements pour les jeunes"]'::jsonb, 0, 'Il pose la question du financement des retraites.', 7),
    ('fbbcd213-67b9-5029-b961-6f8e24aa0ba6'::uuid, 'dfb0ceaa-5c23-5953-ae54-02a5b06a8e55'::uuid, 'La population mondiale est répartie de façon à peu près homogène.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quelques foyers concentrent l’essentiel de l’humanité, face à de vastes vides humains.', 8),
    ('a1d3d6ca-7e42-5b7d-87f7-df964c5cb820'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'Que combine l’IDH ?', 'mcq', '["La richesse, la santé et l’éducation","Le PIB et la superficie","La population et les ressources","Le taux de chômage et l’inflation"]'::jsonb, 0, 'Il donne une image plus juste que le seul PIB.', 1),
    ('5dc7e31b-3f44-56ab-80ad-35fac7339f12'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'Qu’est-ce qu’un pays émergent ?', 'mcq', '["Un pays à croissance rapide et en cours d’industrialisation, mais très inégalitaire","Un pays sortant d’une guerre","Un pays sans industrie","Un pays membre de l’ONU depuis peu"]'::jsonb, 0, 'Chine, Inde, Brésil, Afrique du Sud.', 2),
    ('ce781298-7dd6-5609-81af-ef3d746394cb'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'Que désigne le sigle PMA ?', 'mcq', '["Les pays les moins avancés","Les pays à main-d’œuvre abondante","Les puissances militaires alliées","Les pays méditerranéens associés"]'::jsonb, 0, 'Une cinquantaine de pays, surtout en Afrique.', 3),
    ('2ce0293b-1d82-55ec-be4a-89076de4f8da'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'Pourquoi l’opposition Nord/Sud est-elle devenue insuffisante ?', 'mcq', '["Elle ne rend compte ni de la Chine ni des inégalités internes","Elle est trop récente","Elle ne concerne que l’Europe","Elle a été interdite par l’ONU"]'::jsonb, 0, 'La réalité est plus contrastée qu’une ligne sur une carte.', 4),
    ('bfd664db-3c1f-5190-a611-745784ea3785'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'Où trouve-t-on parfois les inégalités les plus fortes ?', 'mcq', '["À l’intérieur d’un même pays, voire d’une même ville","Uniquement entre continents","Uniquement entre pays voisins","Entre hémisphères"]'::jsonb, 0, 'Bidonvilles et quartiers d’affaires cohabitent.', 5),
    ('05dc8fc0-d984-5a92-892a-5bb0f0ed18a4'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'Quel levier réduit le plus durablement la pauvreté ?', 'mcq', '["La scolarisation, en particulier des filles","L’augmentation des exportations de matières premières","La croissance démographique","L’aide alimentaire d’urgence seule"]'::jsonb, 0, 'Elle agit sur la santé, la fécondité et l’emploi à la fois.', 6),
    ('c58ccaaa-70b5-5af8-81dc-3f4f2c3fc72c'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'Que représentent les transferts d’argent des migrants vers leur pays d’origine ?', 'mcq', '["Une somme supérieure à l’aide publique au développement","Une part négligeable des revenus","Une aide réservée aux États","Un flux interdit par les banques"]'::jsonb, 0, 'Ils irriguent directement les familles.', 7),
    ('7eff486f-c9d6-5cf7-b92a-6922968ee980'::uuid, '8c950ef9-f0b0-510c-afb1-0280efc9bad0'::uuid, 'La pauvreté extrême a augmenté dans le monde depuis trente ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle a fortement reculé, même si les inégalités demeurent.', 8),
    ('fb4c0310-9f41-5c7f-a31e-bf8f63ebfb61'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'Combien de personnes souffrent de la faim dans le monde ?', 'mcq', '["Environ 800 millions","Environ 100 millions","Environ 3 milliards","Environ 50 millions"]'::jsonb, 0, 'Alors que la planète produit assez pour tous.', 1),
    ('d68ec0c4-6ca4-5446-9b95-53686c14b9b4'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'Quelle est la différence entre sous-nutrition et malnutrition ?', 'mcq', '["La sous-nutrition est un manque de calories, la malnutrition un déséquilibre","Ce sont deux mots pour la même chose","La malnutrition ne concerne que les enfants","La sous-nutrition concerne uniquement les pays riches"]'::jsonb, 0, 'On peut manger à sa faim et être carencé.', 2),
    ('3d3ed5de-894e-51c5-a19c-3141cfeeb0bf'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'Qu’est-ce que l’agriculture vivrière ?', 'mcq', '["Une agriculture destinée à nourrir le producteur et sa famille","Une agriculture destinée à l’exportation","Une agriculture entièrement mécanisée","Une agriculture biologique certifiée"]'::jsonb, 0, 'Rendements faibles et forte exposition aux aléas.', 3),
    ('e25144b8-9150-550e-a87a-a87d4f77e294'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'Qu’a été la révolution verte ?', 'mcq', '["Une forte hausse des rendements en Asie par les intrants et l’irrigation","Un mouvement écologiste des années 1970","Le passage au bio en Europe","Un plan de reboisement mondial"]'::jsonb, 0, 'Au prix d’une forte consommation d’eau et d’intrants.', 4),
    ('ff1d928f-19f6-5767-89d1-2e4c206f5c10'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'Quelle part de l’eau douce prélevée l’agriculture consomme-t-elle ?', 'mcq', '["Environ 70 %","Environ 20 %","Environ 40 %","Environ 90 %"]'::jsonb, 0, 'Elle occupe aussi la moitié des terres habitables.', 5),
    ('5e979d17-40e2-5249-b5f6-8d09f60736f7'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'Quelle part de la nourriture produite est perdue ou gaspillée ?', 'mcq', '["Environ un tiers","Environ 5 %","Environ la moitié","Environ 10 %"]'::jsonb, 0, 'Réduire ce gaspillage est l’un des leviers les plus immédiats.', 6),
    ('3d0003f2-ba29-5fd7-896b-df0bf2ff53fb'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'Pourquoi la consommation de viande pose-t-elle un problème ?', 'mcq', '["Elle exige beaucoup de terres, d’eau et de céréales","Elle est moins nutritive","Elle est interdite dans plusieurs pays","Elle se conserve mal"]'::jsonb, 0, 'Il faut plusieurs kilos de céréales pour produire un kilo de viande.', 7),
    ('477ba68b-8022-5f62-a01f-9644f71071cf'::uuid, 'aef721cd-0bf0-597e-8e19-35c12bfbaedb'::uuid, 'La faim dans le monde s’explique d’abord par une production insuffisante.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La production suffit : c’est l’accès à la nourriture qui fait défaut.', 8),
    ('804a143a-2d15-51c0-a22a-c21cd74e8089'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Quelle part de l’eau de la planète est douce ?', 'mcq', '["2,5 %","30 %","10 %","50 %"]'::jsonb, 0, 'Et l’essentiel de cette eau douce est pris dans les glaces.', 1),
    ('e7b4c94b-b56e-5a9a-90e8-7fcd3bf34a84'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Qu’est-ce que le stress hydrique ?', 'mcq', '["Moins de 1 700 m³ d’eau par habitant et par an","Une pollution des nappes","Une inondation saisonnière","Un conflit entre pays riverains"]'::jsonb, 0, 'En dessous de 1 000 m³, on parle de pénurie.', 2),
    ('f1b7e0f6-45f3-5e7c-8aff-289c2dddf2fd'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Quel secteur consomme le plus d’eau ?', 'mcq', '["L’agriculture, avec environ 70 % des prélèvements","L’industrie","Les usages domestiques","La production d’électricité"]'::jsonb, 0, 'L’irrigation en représente l’essentiel.', 3),
    ('7c176f11-f68e-5124-9857-2db190c0298a'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Qu’est-ce que l’eau virtuelle ?', 'mcq', '["L’eau nécessaire pour produire un bien","L’eau des nappes profondes","L’eau recyclée","L’eau de pluie non captée"]'::jsonb, 0, 'Environ 15 000 litres pour un kilo de bœuf.', 4),
    ('4c381f05-67f6-5a41-8004-e769055cae08'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Combien de personnes n’ont pas d’accès sûr à l’eau potable ?', 'mcq', '["Environ 2 milliards","Environ 100 millions","Environ 500 millions","Environ 4 milliards"]'::jsonb, 0, 'L’eau insalubre reste une cause majeure de mortalité infantile.', 5),
    ('c26b578b-11ba-5e5d-ae35-790f84a83453'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Quelle mer intérieure s’est asséchée par surexploitation ?', 'mcq', '["La mer d’Aral","La mer Noire","La mer Caspienne","La mer Morte uniquement"]'::jsonb, 0, 'Le détournement de ses fleuves pour l’irrigation du coton en est la cause.', 6),
    ('5f20ec8e-7486-5e18-8f0e-b8b41e0afbee'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Quelle technique économise l’eau en agriculture ?', 'mcq', '["L’irrigation au goutte-à-goutte","L’irrigation par submersion","Le dessalement","Le pompage profond"]'::jsonb, 0, 'Elle apporte l’eau directement au pied de la plante.', 7),
    ('489e563c-70f0-5157-8ce9-89d179a03378'::uuid, 'a6122998-af31-576a-bd47-ce22110a4c11'::uuid, 'Le dessalement de l’eau de mer est une solution simple et peu coûteuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est coûteux, très énergivore et produit une saumure difficile à rejeter.', 8),
    ('b5cbe467-e27b-5c65-ab33-2006bdf13599'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Quelle part du mix énergétique mondial les énergies fossiles représentent-elles encore ?', 'mcq', '["Environ 80 %","Environ 30 %","Environ 50 %","Environ 10 %"]'::jsonb, 0, 'Pétrole, charbon et gaz dominent toujours.', 1),
    ('601c2905-626f-51d6-bd22-f79b3c92457e'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Quelle énergie renouvelable produit le plus d’électricité dans le monde ?', 'mcq', '["L’hydraulique","L’éolien","Le solaire","La géothermie"]'::jsonb, 0, 'Elle précède l’éolien et le solaire.', 2),
    ('2178a1fa-0d72-5dd5-8ec3-15e480368b7b'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Pourquoi les énergies fossiles posent-elles un problème climatique ?', 'mcq', '["Leur combustion émet du CO₂, principal gaz à effet de serre","Elles consomment trop d’eau","Elles occupent trop d’espace","Elles sont trop chères à extraire"]'::jsonb, 0, 'C’est la première cause du réchauffement.', 3),
    ('aa39552c-d9c3-5425-9429-74fb7d38711e'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Quel est le principal inconvénient du nucléaire ?', 'mcq', '["Les déchets radioactifs et le risque d’accident","Ses fortes émissions de CO₂","Son intermittence","Son occupation d’espace"]'::jsonb, 0, 'Tchernobyl en 1986, Fukushima en 2011.', 4),
    ('ede760b8-5302-5d1b-bf49-b05dfb0694e3'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Quel est le principal inconvénient de l’éolien et du solaire ?', 'mcq', '["Leur intermittence","Leurs émissions de CO₂","Leur coût de combustible","Leur production de déchets radioactifs"]'::jsonb, 0, 'Le vent et le soleil ne se commandent pas.', 5),
    ('9fd49056-ba8d-55ba-a5f6-810434c18110'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Quels sont les trois leviers de la transition énergétique ?', 'mcq', '["Sobriété, efficacité, substitution","Extraction, transport, stockage","Nucléaire, charbon, gaz","Production, distribution, consommation"]'::jsonb, 0, 'Dans cet ordre : consommer moins, puis mieux, puis autrement.', 6),
    ('c70aeab4-f162-5c56-847e-8303249bbfa1'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Combien de personnes n’ont pas accès à l’électricité ?', 'mcq', '["Environ 700 millions","Environ 50 millions","Environ 2 milliards","Environ 100 millions"]'::jsonb, 0, 'Principalement en Afrique subsaharienne.', 7),
    ('3b693d46-1e16-5472-9239-c158bfeebfc2'::uuid, '4affc8a4-f169-5654-b231-7f966d6bdbf0'::uuid, 'Les énergies renouvelables n’ont aucun impact sur l’environnement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles demandent espace, matériaux et infrastructures : la première énergie propre reste celle qu’on ne consomme pas.', 8),
    ('2b09c34c-57c4-558a-b8a2-b411e6d86faf'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'Qu’est-ce que le changement global ?', 'mcq', '["L’ensemble des transformations que les activités humaines font subir à la planète","Le seul réchauffement climatique","Un cycle naturel du climat","La mondialisation économique"]'::jsonb, 0, 'Climat, biodiversité, sols et pollutions y sont liés.', 1),
    ('49e8036a-c0bc-528a-b7d7-6214edd8b74b'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'L’effet de serre est-il un phénomène naturel ?', 'mcq', '["Oui, et il est indispensable : sans lui la Terre serait à −18 °C","Non, il est entièrement dû à l’homme","Oui, mais il est sans effet sur la température","Non, il n’existe que depuis 1950"]'::jsonb, 0, 'Ce sont les activités humaines qui le renforcent.', 2),
    ('c835dd43-421c-550d-b16b-789dd1b5f474'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'De combien la température moyenne mondiale a-t-elle augmenté depuis l’ère préindustrielle ?', 'mcq', '["Environ 1,2 °C","Environ 5 °C","Environ 0,1 °C","Environ 3 °C"]'::jsonb, 0, 'Avec une accélération nette depuis les années 1980.', 3),
    ('da261a9d-d9cd-5963-b093-66f4f7ea6748'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'Quelle est la principale cause de la hausse du niveau des mers ?', 'mcq', '["La dilatation de l’eau et la fonte des glaces continentales","La fonte de la banquise seule","L’augmentation des précipitations","Les marées plus fortes"]'::jsonb, 0, 'La banquise flottante, en fondant, ne fait pas monter le niveau.', 4),
    ('e6221dad-209b-51cc-8360-a1005fdaea85'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'Quelles régions sont les plus menacées par la submersion ?', 'mcq', '["Les États insulaires du Pacifique et les grands deltas","Les zones de montagne","Les déserts chauds","Les régions forestières"]'::jsonb, 0, 'Ce sont souvent celles qui émettent le moins.', 5),
    ('f7e0b3ee-9865-52b9-b164-000b0d9f51f8'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'Que signifie l’atténuation du changement climatique ?', 'mcq', '["Réduire les émissions de gaz à effet de serre","Vivre avec les effets inévitables","Mesurer les températures","Déplacer les populations"]'::jsonb, 0, 'L’adaptation est l’autre volet de la réponse.', 6),
    ('4d10534a-4366-519a-97b2-92345c645b60'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'Quel organisme produit l’expertise scientifique sur le climat ?', 'mcq', '["Le GIEC","L’OMS","L’UNESCO","La FAO"]'::jsonb, 0, 'Les COP sont, elles, les conférences de négociation.', 7),
    ('6af66003-1505-5c2f-ae1c-5d9404316434'::uuid, '23c2c001-2772-5cec-acf7-6c69733719b9'::uuid, 'Il faut choisir entre atténuer le changement climatique et s’y adapter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les deux sont nécessaires : on n’évitera pas tout, et on ne s’adaptera pas à tout.', 8),
    ('7de533f6-3f1e-580f-add9-9cbc99cd62ed'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'Comment définit-on le risque ?', 'mcq', '["Le croisement d’un aléa et d’une vulnérabilité","La probabilité d’un accident seule","Le nombre de victimes possibles","La gravité d’une catastrophe passée"]'::jsonb, 0, 'Sans population exposée, un aléa n’est pas un risque.', 1),
    ('6222293c-1958-5fcf-b2ee-27c8abaebec3'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'Qu’est-ce que l’aléa ?', 'mcq', '["L’événement dangereux possible","La fragilité des populations exposées","La catastrophe elle-même","Le plan de secours"]'::jsonb, 0, 'La vulnérabilité, elle, décrit ce qui est exposé.', 2),
    ('f22a7e02-d5c0-5636-9da7-6daa26266606'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'Quelle catastrophe industrielle a frappé Toulouse en 2001 ?', 'mcq', '["L’explosion de l’usine AZF","Une marée noire","Une rupture de barrage","Un accident nucléaire"]'::jsonb, 0, 'Bhopal en 1984 et Lubrizol en 2019 sont d’autres exemples.', 3),
    ('02a2d999-ac6c-55f8-80db-acf087dae3ef'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'Quelle catastrophe de 2011 mêle risque naturel et risque technologique ?', 'mcq', '["Fukushima","Tchernobyl","Bhopal","Deepwater Horizon"]'::jsonb, 0, 'Un séisme et un tsunami ont déclenché l’accident nucléaire.', 4),
    ('a6040e0f-71e2-56ff-8bd7-ac94aad5aeac'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'Que désigne la directive Seveso ?', 'mcq', '["Une réglementation européenne encadrant les sites industriels dangereux","Un plan de secours communal","Une norme de construction antisismique","Un accord international sur le climat"]'::jsonb, 0, 'Elle impose des obligations renforcées aux sites classés.', 5),
    ('72d9b2d6-7392-5b8c-b547-b87d14a14d53'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'À quoi sert un PPRT ?', 'mcq', '["À interdire ou encadrer les constructions autour d’un site dangereux","À indemniser les victimes","À financer la dépollution","À former les pompiers"]'::jsonb, 0, 'C’est un outil d’aménagement du territoire.', 6),
    ('0d0460e8-8dc6-5659-94b3-968d4bbdd764'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'Pourquoi la vulnérabilité est-elle plus grande dans les pays pauvres ?', 'mcq', '["Normes moins strictes, habitat proche des sites et secours limités","Les aléas y sont plus fréquents","Les usines y sont plus nombreuses","Le climat y est plus rude"]'::jsonb, 0, 'À aléa égal, les conséquences y sont bien plus lourdes.', 7),
    ('28812b74-e02d-555c-b0d3-d1c95ac90893'::uuid, 'd3bb6d70-f9c1-5af9-a40b-b84d1e08dfcd'::uuid, 'La prévention consiste d’abord à supprimer l’aléa industriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne le supprime pas : on réduit la vulnérabilité par la réglementation et l’aménagement.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 306 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 306 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
